Take $j_0 \in \mathbb N$ such that for all $j \ge j_0$ we have
 \begin{equation}
  \frac{\rho(0,(0,0,4^i(1+\eta)^ks^2))}{\lambda_j^{-1} d_1(0,(0,0,4^i(1+\eta)^k\lambda_j^2s^2))} \in \left(1 - \frac{1}{100}, 1 + \frac{1}{100} \right), \end{equation}
 for all $(i,k) \in \{0,1,\dots,2 m\ell\} \times \{0,\dots,N-1\}$.  Let $n \in \mathbb Z$ be such that $(\lambda_j s)^2 \in \left[ \frac{1}{2} 4^{-n}, 2 \cdot 4^{-n}\right)$.  By Lemma~\ref{lma:norepeat}, we have that there exists some $i \in \{0,\dots,m \ell\}$ such that $a(n+i) \neq a(n+ i + m\ell)$.  We may suppose without loss of generality that $a(n+i) = 1$ so $a(n+i+m\ell) = 0$.

We have that there exists some $k \in \{0,\dots,N-1\}$ such that $4^i(1+\eta)^k \lambda_j^2 s^2 \in ((1-\eta) 4^{n+i},(1+\eta) 4^{n+i})$.  Thus, because $a(n+i) = 1$, we have that
 \begin{equation} \rho(0,(0,0,4^i (1+\eta)^k s^2)) \overset{\eqref{e:upperbound} \wedge \eqref{e:precision}}{\leq} 0.52 d_{cc}(0,(0,0,4^i (1+\eta)^k s^2)).
 \end{equation}

On the other hand, because $a(n+i+m\ell) = 0$ and $$4^{i+m\ell}(1+\eta)^k \lambda_j^2 s^2 \in \left( \frac{1}{2} 4^{n+i+m\ell}, 2 \cdot 4^{n+i+m\ell} \right),$$ we have that
 \begin{eqnarray*}
   \rho(0,(0,0,4^{i+m\ell} (1+\eta)^k s^2)) &\overset{\eqref{e:sqrt3-lower} \wedge \eqref{e:precision}}{\geq} &\frac{99}{100} \frac{1}{\sqrt{3}} d_{cc}(0,(0,0,4^{i+m\ell} (1+\eta)^k s^2)) \\
   &\geq& 0.55 d_{cc}(0,(0,0,4^{i+m\ell}(1+\eta)^k s^2)), \\
   &=& 0.55 \cdot 2^{m\ell} d_{cc}(0,(0,0,4^i(1+\eta)^k s^2)).
 \end{eqnarray*}

Then by the self-similarity of $\rho$ with ratio $2^{m\ell}$ we have
  \begin{eqnarray*}
   \rho(0,(0,0,4^i (1+\eta)^k s^2)) & = & 2^{-m\ell}\rho(0,(0,0,4^{i+m\ell} (1+\eta)^k s^2))\\
   & \ge & 0.55 d_{cc}(0,(0,0,4^i(1+\eta)^k s^2)).
  \end{eqnarray*}
  This contradicts \eqref{eq:finalcontra}.

